(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(y * 0.02 + t * 0.3) * 15 + Math.cos(x * 0.015 - t * 0.2) * 10;
  const wy = Math.sin(x * 0.018 - t * 0.25) * 12 + Math.cos(y * 0.022 + t * 0.35) * 8;
  const px = x + wx, py = y + wy;
  const s = [
    [160 + Math.sin(t * 0.6) * 100, 80 + Math.cos(t * 0.4) * 50],
    [320 + Math.cos(t * 0.5) * 100, 160 + Math.sin(t * 0.7) * 50],
    [240 + Math.sin(t * 0.3 + 2) * 140, 120 + Math.cos(t * 0.5 + 1) * 90],
    [100 + Math.cos(t * 0.8 + 1) * 80, 180 + Math.sin(t * 0.35) * 60],
    [380 + Math.sin(t * 0.45 + 3) * 70, 60 + Math.cos(t * 0.65) * 40],
    [240 + Math.sin(t * 0.2) * 160, 120 + Math.cos(t * 0.15) * 100]
  ];
  const freq = [0.08, 0.1, 0.06, 0.09, 0.07, 0.05];
  const spd = [2, 1.7, 2.3, 1.9, 2.1, 1.5];
  let act = 0, inh = 0;
  for (let i = 0; i < 6; i++) {
    const d = Math.sqrt((px - s[i][0]) ** 2 + (py - s[i][1]) ** 2);
    const w = Math.sin(d * freq[i] - t * spd[i]);
    if (i < 3) act += w; else inh += w;
  }
  act /= 3; inh /= 3;
  const c1 = Math.sin(px * 0.05 + py * 0.03 + t * 0.8);
  const c2 = Math.sin(px * 0.03 - py * 0.05 + t * 1.1);
  const c3 = Math.sin((px + py) * 0.15 + t * 3) * 0.15;
  const c4 = Math.sin((px - py) * 0.12 - t * 2.5) * 0.15;
  const inhFull = inh + (c1 + c2) / 2 * 0.6;
  const reaction = act - inhFull * 0.8 + c3 + c4;
  const dist = Math.sqrt((px - cx) ** 2 + (py - cy) ** 2);
  const ang = Math.atan2(py - cy, px - cx);
  const radial = Math.sin(dist * 0.04 - t * 1.5);
  const angular = Math.sin(ang * 6 + t * 0.4);
  const spiral = Math.sin(dist * 0.03 + ang * 3 - t * 1.2) * 0.3;
  const pat2 = Math.tanh((radial + angular * 0.5 + spiral) * 2);
  const edge = Math.abs(Math.tanh(reaction * 2.5));
  const micro = Math.sin(px * 0.3 + py * 0.2 + t * 4) * Math.sin(px * 0.2 - py * 0.3 + t * 3) * 0.06 * edge;
  const spot = Math.tanh(reaction * 2.5);
  const blend = spot * 0.5 + pat2 * 0.35 + micro;
  const v = Math.max(0, Math.min(1, blend * 0.5 + 0.5));
  const pal = [
    [12, 12, 52], [18, 68, 100], [35, 145, 128],
    [195, 170, 55], [200, 85, 55], [110, 28, 65], [12, 12, 52]
  ];
  const idx = v * (pal.length - 1), i = Math.min(idx | 0, pal.length - 2), f = idx - i;
  const lum = 0.8 + Math.sin(reaction * Math.PI) * 0.2;
  const vig = 0.65 + 0.35 * Math.max(0, 1 - dist / 240);
  return [
    Math.min(255, (pal[i][0] + (pal[i+1][0] - pal[i][0]) * f) * lum * vig) | 0,
    Math.min(255, (pal[i][1] + (pal[i+1][1] - pal[i][1]) * f) * lum * vig) | 0,
    Math.min(255, (pal[i][2] + (pal[i+1][2] - pal[i][2]) * f) * lum * vig) | 0
  ];
}
